{
 "title": "地震防災対策特別措置法の改正",
 "lead": {
  "es": "地震《じしん》にそなえる急《いそ》ぎの事業《じぎょう》に 国《くに》がお金《かね》を多《おお》く出《だ》すしくみなどを、5年《ねん》のばした法律《ほうりつ》です。",
  "hs": "｜地震《じしん》防災｜緊急《きんきゅう》事業への国の負担や補助の｜特例《とくれい》などの期限を5年間のばし、令和8年3月31日までとした法律です。",
  "std": "地震防災緊急事業に係る国の負担・補助の特例等の措置の有効期限を、5年間延長して令和8年3月31日までとした法律です。",
  "univ": "地震防災対策特別措置法の実施の状況に鑑み、地震防災緊急事業に係る国の負担又は補助の特例等の措置の有効期限を令和8年3月31日まで5年間延長し、地震防災緊急事業を引き続き推進する法律。"
 },
 "facts": [
  {
   "es": "地震《じしん》にそなえる急《いそ》ぎの事業《じぎょう》（地震《じしん》防災《ぼうさい》緊急《きんきゅう》事業《じぎょう》）に、国《くに》がお金《かね》を出《だ》す割合《わりあい》などのとくべつな決《き》まりを、5年《ねん》のばして 令和《れいわ》8年《ねん》3月《がつ》31日《にち》までにします。",
   "hs": "｜地震《じしん》防災｜緊急《きんきゅう》事業にかかる国の負担や補助の｜特例《とくれい》などの｜措置《そち》の期限を、5年間のばして令和8年3月31日までとする。",
   "std": "地震防災緊急事業に係る国の負担・補助の特例等の措置の有効期限を、5年間延長して令和8年3月31日までとします。",
   "univ": "地震防災緊急事業に係る国の負担又は補助の特例等の措置の有効期限を令和8年3月31日まで5年間延長する。"
  },
  {
   "es": "これにより、地震《じしん》にそなえる急《いそ》ぎの事業《じぎょう》を、引《ひ》き続《つづ》き進《すす》めます。",
   "hs": "これにより、｜地震《じしん》防災｜緊急《きんきゅう》事業を引き続き進める。",
   "std": "これにより、地震防災緊急事業を引き続き推進します。",
   "univ": "これにより、地震防災緊急事業を引き続き推進する。"
  }
 ]
}
